/**
 * The same fifty with their tier resolved from the lists in `coverage.js`.
 *
 * Derived, never typed: move a state between the tiers there and the map
 * repaints, so the country can no more disagree with the counts beside it
 * than the region ledger can. The order is west to east, which is the order
 * the states are drawn in when the band arrives.
 *
 * @type {import("./types").StateShape[]}
 */
export const stateShapes = outlines.map((state) => ({
  ...state,
  // Every state is named in exactly one of the two lists — the forty seven
  // core states plus the three we are expanding into — so one test settles it.
  tier: /** @type {"core"|"expanding"} */ (
    coreStates.includes(state.name) ? "core" : "expanding"
  ),
}));
